function davidWorkerLinkPage(){
 N("content").innerHTML=Ct("Operator DPP профил","Google/Gmail вход → личен Worker ID → еднократен код → DAVID DPP синхронизация.")+
 '<div class="card"><h2>Служебен DPP профил</h2><p class="muted">1. Влез с одобрения служебен Gmail. 2. Генерирай личен код. 3. Отвори DAVID → DPP и въведи кода. 4. Провери синхронизацията.</p><p id="davidProfileStatus" class="muted">Проверявам одобрението на оператора...</p><p class="tiny">Worker ID: <span id="davidProfileWorker">Проверка...</span></p><p class="tiny">Organization ID: <span id="davidProfileOrg">Проверка...</span></p><p class="tiny">Примерен формат: <code>#1948a!</code>. Истинският код е по-дълъг, уникален и не се споделя между оператори.</p><div id="davidProfileCode" class="chip" style="display:none;font-size:20px;letter-spacing:2px;max-width:max-content;margin:14px 0"></div><div class="row"><button id="davidGenerateCode" class="btn primary" disabled>Генерирай личен DPP код</button><button id="davidCopyCode" class="btn" disabled>Копирай кода</button><a class="btn" href="https://david-os-rust.vercel.app/work" target="_blank" rel="noopener noreferrer">Отвори DAVID → DPP</a><button id="davidRefreshLink" class="btn">Провери синхронизацията</button></div><p class="tiny" style="margin-top:12px">Валидност: 12 минути; еднократно използване. Само изрично одобрени оператори могат да свържат DAVID. Google входът сам по себе си не дава права.</p></div>';
 let activeCode=null,codeExpiresAt=0;
 const status=N("davidProfileStatus"),gen=N("davidGenerateCode"),copy=N("davidCopyCode"),refresh=N("davidRefreshLink");
 const hideCode=()=>{activeCode=null;codeExpiresAt=0;copy.disabled=true;N("davidProfileCode").style.display="none";N("davidProfileCode").textContent=""};
 async function checkLinkStatus(){
  if(g.view!=="profile")return;
  refresh.disabled=true;
  try{
   // Direct Supabase RLS read: independent from unavailable Vercel bridge secrets.
   const {data:ident,error:identityError}=await g.db.from("david_worker_identities")
     .select("worker_id,organization_id,active").eq("user_id",g.user.id).maybeSingle();
   if(identityError)throw identityError;
   if(!ident?.active)throw Error("Служебният акаунт не е активен в Admin → Workers.");
   const {data:linkRows,error:linksError}=await g.db.from("david_worker_links")
     .select("worker_id").eq("worker_id",ident.worker_id).is("revoked_at",null).limit(1);
   if(linksError)throw linksError;
   const info={...ident,david_linked:!!linkRows?.length,integration_ready:true,david_bridge_ready:false};
   if(g.view!=="profile")return;
   N("davidProfileWorker").textContent=info.worker_id||"Неизвестен";
   N("davidProfileOrg").textContent=info.organization_id||"Неизвестна";
   if(info.david_linked){hideCode();status.textContent="✅ DAVID DPP: синхронизиран с личния Worker ID";gen.disabled=true}
   else{
    status.textContent="✅ Gmail профилът е активен. Можеш да издадеш личен код. DAVID OS синхронизацията още изисква свързване от Митко.";
    gen.disabled=!info.integration_ready;
   }
  }catch(err){if(g.view==="profile"){status.textContent="Служебен профил: "+(err?.message||"Недостъпен");gen.disabled=true}}
  finally{refresh.disabled=false}
 }
 gen.onclick=async()=>{
  gen.disabled=true;hideCode();
  try{
   const {data:info,error:issueError}=await g.db.rpc("david_generate_link_code");
   if(issueError)throw issueError;
   if(!info?.code||!info.expires_at)throw Error("Не е издаден код. Опитай отново.");
   activeCode=info.code;codeExpiresAt=Date.parse(info.expires_at)||0;
   const element=N("davidProfileCode");element.textContent=activeCode;element.style.display="block";
   copy.disabled=false;
   status.textContent="Кодът е издаден до "+new Date(info.expires_at).toLocaleTimeString("bg-BG")+". За синхронизация DAVID OS трябва да има работеща проверка на кода. Засега свързването не е потвърдено.";
   gen.disabled=false;
   const mintedCode=activeCode;
   setTimeout(()=>{if(g.view==="profile"&&activeCode===mintedCode&&codeExpiresAt<=Date.now()){hideCode();status.textContent="Кодът изтече. Генерирай нов."}},Math.max(0,codeExpiresAt-Date.now())+1000);
  }catch(err){status.textContent=err?.message||"Генерирането е недостъпно";gen.disabled=false}
 };
 copy.onclick=async()=>{
  if(!activeCode||Date.now()>=codeExpiresAt){hideCode();return}
  try{await navigator.clipboard.writeText(activeCode);status.textContent="Кодът е копиран. Въведи го в DAVID → DPP."}
  catch{status.textContent="Неуспешно копиране. Маркирай кода ръчно."}
 };
 refresh.onclick=checkLinkStatus;
 checkLinkStatus();
}
