  const phone=(value("phone")?.value||"").trim(),source=(value("source")?.value||"").trim();
  const city=(value("city")?.value||"").trim(),verified=!!value("verified")?.checked,approve=!!value("approve")?.checked;
  if(approve&&!verified)return re("За разрешен ръчен контакт потвърди проверката и правното основание.");
  btn.disabled=true;
  const{data,error}=await g.db.rpc("david_admin_update_business_contact",{
   p_company_id:id,p_city:city,p_business_phone:phone,p_phone_source:source,
   p_approve_manual_contact:approve,p_verified_by_admin:verified
  });
